    by_id[2292]['additional_source_access_review']={'reviewer':delegated_reader,'current_candidate_read':True,'original_text_obtained':False,'attempts':[{'url':'https://zh.wikisource.org/wiki/關侯祖墓碑記','result':'404'},{'url':'https://zh.wikisource.org/wiki/解舂集','result':'404'},{'url':'https://zh.wikisource.org/wiki/解舂集_(四庫全書本)','result':'404'}],'conclusion':'没有取得原文或具体版本定位，不能核胡氏句或立碑著录年；网页404不等史书无载，不新增清康熙某年。历史BDnull，178194231为未证游戏估算。'}


    # Correct an earlier reader segmentation error: 王牢之高祖 means 王牢的高祖.
    ev=checked_excerpt(SOURCE/'_cache/chunks/sl_08.txt','王牢太原祁人也髙祖宏河东太守绵竹侯',500);ev.update(source_reader_agent='/root/chronology_0850_3999',verification='individually_read_correct_candidate_genealogical_passage',source_layer='late_Ming_recompiled_Shiliuguo_Chunqiu_not_Cui_Hong_original')
    row=by_id[1039]
    for item in row['source_identity_adjudications']:
        if item['source_key'].startswith('sl:'):
            row['retracted_unlocated_source_placeholder']=item.copy()
            item.clear();item.update(source_key='sl:sl_08:6:王宏',identity_verdict='located_Wang_Lao_ancestor_Hong_genealogical_branch_whole_record_still_mixed',identity_basis='王牢之高祖中的之为结构助词；原SL王牢高祖宏，不是三字人名王牢之。宏姓承王牢家系，太原祁河东守绵竹侯；未与其他王宏分支强合。',**ev)
    song_ev=checked_excerpt(SOURCE/'_cache/texts/宋书.txt','王玄谟，字彦德，太原祁人也。六世祖宏，河东太守，绵竹侯',900);song_ev.update(source_reader_agent='/root/chronology_0850_3999',verification='individually_read_full_genealogical_intro_and_qualification',source_qualification='原文其自叙云尔，保存家族自述来源限定；不是史臣独立确认祖谱或生卒')
    row['evidence'].extend([ev,song_ev]);row['review_scope']='individually_read_current_cited_subject_passages'
    row['source_identity_branches']=[v for v in row['source_identity_branches'] if not any(k.startswith('sl:') for k in v.get('source_keys',[]))]+[{'subject':'王牢高祖王宏/王玄谟六世祖宏家谱自述支','source_keys':['sl:sl_08:6:王宏'],'original_passage_located':True,'source_qualification':'SL晚明重编源层；独宋书记录其自叙云尔的家谱声称，不当两独史证。宋称从叔王允难后北迁与HHS长文192死未独桥，不能直接合或套日期。'}]
    row['source_reference_location_correction']={'status':'actual_genealogical_subject_passage_obtained','correction':'此前把王牢之高祖误断三字人名王牢之导致未定位，现按官爵回查找到王牢高祖宏；原卷指针不需改。','original_source_pointer_correct':True}
    old=row.get('batch_review_note');row['previous_unlocated_review_note']=old
    if old:row['unresolved']=[v for v in row['unresolved'] if v!=old]
    row.update(batch_review_note='五key原段现均实际读：汉长文右扶风192遇害与魏晋正宗王弼兄/华表司隶分支仍混；SL已真定位王牢高祖宏，独宋书王玄谟六世祖宏从叔允难北迁但原称其自叙云尔，保家谱来源批评。之字原先误作人名一部分，纠正未定位结论；不能因此将全实体合一或把192死套祖谱支。',batch_review_id='0850_batch_204_corrected_genealogical_reference_location',historical_birth=None,historical_death=None,review_status='identity_conflict',source_identities_all_adjudicated=False)
    current_identity_ids_read.discard(1039)

    # Distinguish source review completed with no adoptable date from references not yet checked.
    for reviewed_row in results:
        if reviewed_row.get('review_scope')!='individually_read_current_cited_subject_passages':continue
        full_identity=reviewed_row['id'] in current_identity_ids_read or reviewed_row.get('source_identities_all_adjudicated') is True
        date_status={}
        for part in ('birth','death'):
            if reviewed_row.get('historical_'+part) is not None:date_status[part]='evidence_recorded_with_precision' if full_identity else 'evidence_recorded_identity_still_on_hold'
            elif reviewed_row.get('historical_identity_verified') is False and reviewed_row.get('literary_character_attested'):date_status[part]='historical_identity_not_established_literary_subject'
            elif not full_identity:date_status[part]='not_adopted_pending_source_identity_adjudication'
            elif reviewed_row.get('source_date_conflicts') or reviewed_row.get('source_branch_date_conflicts'):date_status[part]='source_conflict_not_uniquely_resolved'
            else:date_status[part]='unknown_in_consulted_sources'
        reviewed_row['historical_date_status']=date_status
        reviewed_row['date_review_scope_limit']='Only individually consulted current cited passages and recorded supplementary evidence; not an exhaustive claim about all historical literature.'

    by_id[3848]['historical_date_status']={'birth':'unknown_in_consulted_sources','death':'source_conflict_not_uniquely_resolved'}

    for row in results:
        if row["id"] in current_identity_ids_read:
            row["source_identities_all_adjudicated"] = True
            row["identity_status"] = "current_source_keys_identity_corroborated"
        elif len(row["keys"]) == 1 and row.get("review_scope", "").startswith("individually_read") and row["review_status"] == "source_checked_dates_unknown":
            # This branch is reached only for the manually enumerated notes above.
            row["source_identities_all_adjudicated"] = True
        for field in ("birth", "death"):
            if row[f"historical_{field}"] is not None:
                stale = f"{field}_date_not_independently_corroborated"
                row["unresolved"] = [item for item in row["unresolved"] if item != stale]
        if row.get('review_scope')!='individually_read_current_cited_subject_passages':
            row["historical_date_status"] = {
                field: ("evidence_recorded_with_precision" if row[f"historical_{field}"] else
                        "unknown_in_consulted_passage" if row["review_status"] == "source_checked_dates_unknown" else
                        "not_yet_individually_verified") for field in ("birth", "death")}
    for pid, current in retired_current.items():
        if pid not in by_id:
            continue
        row = by_id[pid]
        row['archived_previous_source_review'] = {k: row.get(k) for k in ('keys','name','historical_birth','historical_death','evidence','verified_activity','source_identity_adjudications','review_status','identity_status')}
        row['archived_previous_source_review']['name'] = candidates[current['merged_from_keys'][0]]['name']
        row['previous_source_keys'] = row['keys'][:]
        row.update(keys=current['keys'][:],name=current['name_full'],historical_birth=None,historical_death=None,
            current_game={k:current[k] for k in ('birth','appear','death')},proposed_appear=None,
            review_status='needs_further_research',identity_status='retired_source_slot',
            source_identities_all_adjudicated=False,external_merged_into=current['merged_into'],
            retired_source_slot=True,duplicate_of=None,verified_activity=[])
        row['unresolved'].append('Current roster externally retired this slot and moved source keys; archive does not adjudicate the whole target identity.')
        all_by_id[pid]['keys'] = current['keys'][:]
    cross_path = ROOT / "data/persons/reviews/cross_shard_0850.json"
    cross_path.write_text(json.dumps({"decisions": cross_decisions}, ensure_ascii=False, indent=2), encoding="utf-8")
    out_path = ROOT / "data/persons/reviews/review_0850_3999.jsonl"
    out_path.parent.mkdir(parents=True, exist_ok=True)
    assert all(row.get('duplicate_of') is None or row['review_status']=='duplicate' for row in results), 'redirect on a nonduplicate record'
    for initial in by_id:
        visited=set();target=initial
        while target in by_id and by_id[target].get('duplicate_of') is not None:
            assert target not in visited, ('duplicate_cycle',initial,target)
            visited.add(target);target=by_id[target]['duplicate_of']
    out_path.write_text("".join(json.dumps(row, ensure_ascii=False)+"\n" for row in results), encoding="utf-8")
    assert len(results) == len({row["id"] for row in results}) == 3150
    assert {row["id"] for row in results} == set(range(850, 4000))
    assert all(row["keys"] == all_by_id[row["id"]]["keys"] for row in results)
    assert all(row["historical_birth"] is None and row["historical_death"] is None
        for row in results if row["review_status"] == "identity_conflict")
    assert all(by_id[pid]["historical_death"] is None for pid in (899, 1375, 1857, 2466, 2968, 2997, 3661))
    assert len(cross_decisions) == 11
    assert all(row["keys"] == all_by_id[row["id"]]["keys"] for row in cross_decisions)
